        System.setProperty("karaf.etc", "src/test/resources/etc2");
        cc = new ClientConfig(new String[0]);
        assertThat(cc.getUser(), equalTo("test"));

        if (etc != null) {
            System.setProperty("karaf.etc", etc);
        }
    }

}
